#!/usr/bin/env python3
"""Merge results/*.json into LEADERBOARD.md, sorted by ratio."""
import glob
import json
import os
import re

rows = {}

def lang_of(name):
    p = os.path.join("submissions", name, "README.md")
    if os.path.exists(p):
        m = re.search(r"(?im)^\s*language\s*[:=]\s*(.+)$", open(p).read())
        if m:
            return m.group(1).strip()
    return ""

for f in glob.glob("results/*.json"):
    try:
        r = json.load(open(f))
    except Exception:
        continue
    if r.get("verdict") == "QUALIFIED":
        name = r["submission"]
        r["language"] = lang_of(name)
        rows[name] = r

# keep rows already in the file (their historical scores stand)
if os.path.exists("LEADERBOARD.md"):
    text = open("LEADERBOARD.md").read()
    for m in re.finditer(
        r"^\|\s*([^|]*)\|\s*([^|]*)\|\s*([^|]*)\|\s*([^|]*)\|\s*([^|]*)\|\s*([^|]*)\|\s*([^|]*)\|\s*$",
        text, re.M,
    ):
        cells = [c.strip() for c in m.groups()]
        if len(cells) < 7 or cells[1] in ("submission", "---", ":---", ""):
            continue
        name = cells[1].strip("`")
        if name in rows:
            continue
        try:
            ratio = float(cells[3].rstrip("x"))
        except ValueError:
            continue
        rows[name] = {
            "submission": name, "language": cells[2], "ratio": ratio,
            "rps": cells[4], "p99_ms": cells[5], "scored_at": cells[6],
        }

def sortkey(r):
    return r["ratio"] if isinstance(r["ratio"], (int, float)) else -1

order = sorted(rows.values(), key=sortkey, reverse=True)

medals = ["🥇", "🥈", "🥉"]
out = ["# 🥤 The Leaderboard\n",
       "Every entry is scored by CI under the same rules: your requests per second"
       " divided by the baseline's, measured on the same runner in the same run."
       " Higher is better. The date is the last time it was measured.\n",
       "| # | submission | language | ratio | rps | p99 (ms) | scored |",
       "|---|---|---|---|---|---|---|"]

for i, r in enumerate(order):
    medal = medals[i] + " " if i < 3 else str(i + 1)
    ratio = f"{r['ratio']:.2f}x" if isinstance(r["ratio"], (int, float)) else r["ratio"]
    out.append(f"| {medal} | `{r['submission']}` | {r.get('language','')} | {ratio} | {r['rps']} | {r['p99_ms']} | {r['scored_at']} |")

out.append("")
out.append("Do not edit this file by hand. It is written by a robot with strong"
           " opinions and stronger ping-pong skills: `.github/scripts/update_leaderboard.py`.")
out.append("")
open("LEADERBOARD.md", "w").write("\n".join(out))
print("leaderboard rebuilt with", len(order), "rows")
